-- DRAKMOR ģildes. Izpildīt Supabase SQL Editor vienreiz.
create table if not exists public.guilds (id bigint generated always as identity primary key, name text not null unique check(char_length(name) between 3 and 30), description text not null default '', owner_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.guild_members (user_id uuid primary key references auth.users(id) on delete cascade, guild_id bigint not null references public.guilds(id) on delete cascade, joined_at timestamptz not null default now());
create index if not exists guild_members_guild_id_idx on public.guild_members(guild_id);
alter table public.guilds enable row level security;
alter table public.guild_members enable row level security;
revoke all on public.guilds, public.guild_members from anon, authenticated;
create or replace function public.guild_list() returns table(id bigint,name text,description text,members bigint) language sql stable security definer set search_path='' as $$select g.id,g.name,g.description,count(m.user_id) from public.guilds g left join public.guild_members m on m.guild_id=g.id group by g.id order by count(m.user_id) desc,g.name limit 100$$;
create or replace function public.guild_my() returns table(id bigint,name text,description text,owner_id uuid,members bigint) language sql stable security definer set search_path='' as $$select g.id,g.name,g.description,g.owner_id,(select count(*) from public.guild_members m where m.guild_id=g.id) from public.guilds g join public.guild_members gm on gm.guild_id=g.id where gm.user_id=auth.uid()$$;
create or replace function public.guild_create(p_name text,p_description text default '') returns void language plpgsql security definer set search_path='' as $$declare v_id bigint;begin if auth.uid() is null then raise exception 'Pieslēdzies kontam';end if;if exists(select 1 from public.guild_members where user_id=auth.uid()) then raise exception 'Tu jau esi ģildē';end if;if length(trim(p_name)) not between 3 and 30 then raise exception 'Nosaukumam jābūt 3–30 simboliem';end if;insert into public.guilds(name,description,owner_id) values(trim(p_name),left(coalesce(p_description,''),200),auth.uid()) returning id into v_id;insert into public.guild_members(user_id,guild_id) values(auth.uid(),v_id);end$$;
create or replace function public.guild_join(p_guild_id bigint) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Pieslēdzies kontam';end if;if exists(select 1 from public.guild_members where user_id=auth.uid()) then raise exception 'Tu jau esi ģildē';end if;if not exists(select 1 from public.guilds where id=p_guild_id) then raise exception 'Ģilde nav atrasta';end if;insert into public.guild_members(user_id,guild_id) values(auth.uid(),p_guild_id);end$$;
create or replace function public.guild_leave() returns void language plpgsql security definer set search_path='' as $$declare v_guild bigint;v_owner uuid;begin select g.id,g.owner_id into v_guild,v_owner from public.guilds g join public.guild_members m on m.guild_id=g.id where m.user_id=auth.uid();if v_guild is null then raise exception 'Tu neesi ģildē';end if;if v_owner=auth.uid() then if (select count(*) from public.guild_members where guild_id=v_guild)>1 then raise exception 'Vadītājs nevar izstāties, kamēr ģildē ir citi dalībnieki';end if;delete from public.guilds where id=v_guild;else delete from public.guild_members where user_id=auth.uid();end if;end$$;
revoke all on function public.guild_list(),public.guild_my(),public.guild_create(text,text),public.guild_join(bigint),public.guild_leave() from public,anon;
grant execute on function public.guild_list(),public.guild_my(),public.guild_create(text,text),public.guild_join(bigint),public.guild_leave() to authenticated;
